<?php get_header(); ?><main id="content" class="container article-layout"><?php while(have_posts()): the_post(); ?><article class="post"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Trang chủ</a> / <?php the_category(', '); ?></div><h1><?php the_title(); ?></h1><div class="post-meta">Đăng ngày <?php echo esc_html(get_the_date('d/m/Y')); ?> · <?php echo esc_html(get_the_author()); ?><?php if(get_the_modified_date('Ymd') !== get_the_date('Ymd')) echo ' · Cập nhật '.esc_html(get_the_modified_date('d/m/Y')); ?></div><?php if(has_post_thumbnail()) the_post_thumbnail('large',array('class'=>'featured-image')); ?><div class="entry-content"><?php the_content(); ?></div><aside class="post-note">Bài viết mang tính giáo dục và tham khảo; không phải khuyến nghị mua, bán chứng khoán.</aside><?php the_post_navigation(); ?></article><?php endwhile; ?></main><?php get_footer(); ?>
